#include <stdio.h>

int main(void)
{
    int a[50], n, i, sum = 0;
    float avg;

    printf("How many elements? ");
    scanf("%d", &n);

    printf("Enter %d elements: ", n);
    // run-time initialization
    for (i = 0; i < n; i++)
        scanf("%d", &a[i]);

    for (i = 0; i < n; i++)
        sum = sum + a[i];
    avg = (float) sum / n;

    printf("Elements: ");
    for (i = 0; i < n; i++)
        printf("%d ", a[i]);
    printf("\nSum = %d\nAverage = %.2f\n", sum, avg);
    return 0;
}

#include <stdio.h>

int main(void)
{
    int a[50], n, i, max, min;

    printf("How many elements? ");
    scanf("%d", &n);
    printf("Enter %d elements: ", n);
    for (i = 0; i < n; i++)
        scanf("%d", &a[i]);

    // assume first is max and min
    max = min = a[0];
    for (i = 1; i < n; i++)
    {
        if (a[i] > max)
            max = a[i];
        if (a[i] < min)
            min = a[i];
    }
    printf("Largest = %d\nSmallest = %d\n", max, min);
    return 0;
}

#include <stdio.h>

int main(void)
{
    int a[50], n, i, key, pos = -1;

    printf("How many elements? ");
    scanf("%d", &n);
    printf("Enter %d elements: ", n);
    for (i = 0; i < n; i++)
        scanf("%d", &a[i]);

    printf("Enter element to search: ");
    scanf("%d", &key);

    for (i = 0; i < n; i++)
    {
        if (a[i] == key)
        {
            pos = i;
            // stop at first match
            break;
        }
    }

    if (pos != -1)
        printf("%d found at index %d (position %d)\n", key, pos, pos + 1);
    else
        printf("%d not found\n", key);
    return 0;
}

#include <stdio.h>

int main(void)
{
    int a[50], n, i, j, temp;

    printf("How many elements? ");
    scanf("%d", &n);
    printf("Enter %d elements: ", n);
    for (i = 0; i < n; i++)
        scanf("%d", &a[i]);

    // passes
    for (i = 0; i < n - 1; i++)
    {
        // comparisons
        for (j = 0; j < n - 1 - i; j++)
        {
            // swap if out of order
            if (a[j] > a[j + 1])
            {
                temp = a[j];
                a[j] = a[j + 1];
                a[j + 1] = temp;
            }
        }
    }

    printf("Sorted array: ");
    for (i = 0; i < n; i++)
        printf("%d ", a[i]);
    printf("\n");
    return 0;
}

#include <stdio.h>

int main(void)
{
    int a[] = {11, 22, 33, 44, 55, 66};
    // number of elements
    int n = sizeof(a) / sizeof(a[0]);
    int i, temp;

    for (i = 0; i < n / 2; i++)
    {
        // swap first and last
        temp = a[i];
        a[i] = a[n - 1 - i];
        a[n - 1 - i] = temp;
    }

    printf("Reversed: ");
    for (i = 0; i < n; i++)
        printf("%d ", a[i]);
    printf("\n");
    return 0;
}

#include <stdio.h>

int main(void)
{
    int a[50] = {10, 20, 30, 40, 50};
    int n = 5, i, pos, item;

    printf("Enter element and position (1 to %d): ", n + 1);
    scanf("%d %d", &item, &pos);

    if (pos < 1 || pos > n + 1)
    {
        printf("Invalid position\n");
        return 1;
    }

    // shift right
    for (i = n - 1; i >= pos - 1; i--)
        a[i + 1] = a[i];
    a[pos - 1] = item;
    n++;

    printf("Array after insertion: ");
    for (i = 0; i < n; i++)
        printf("%d ", a[i]);
    printf("\n");
    return 0;
}

